191	    public void setTelephone(String telephone) {
192	        this.telephone = telephone;
193	    }
194	
195	    /**
196	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
197	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
198	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
199	     * split by taking its leading digit as the (minimal) country code.
200	     */
201	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
202	
203	    /**
204	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
205	     * single space, then the national digits grouped in threes from the left (e.g. the stored
206	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
207	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
208	     * digit string.
209	     *
210	     * @return the human-readable telephone, or the stored value when it cannot be formatted
211	     */
212	    public String getTelephoneDisplay() {
213	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
214	            return this.telephone;
215	        }
216	        String digits = this.telephone.substring(1);
217	        String countryCode = extractCountryCode(digits);
218	        String national = digits.substring(countryCode.length());
219	        StringBuilder display = new StringBuilder("+").append(countryCode);
220	        for (int i = 0; i < national.length(); i += 3) {
221	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
222	        }
223	        return display.toString();
224	    }
225	
226	    /**
227	     * Splits the country code off an E.164 digit string (country code followed by national digits,
228	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
229	     * whose required national-number length matches the remaining digits is preferred; failing that,
230	     * the leading digit is used as the country code.
231	     *
232	     * @param digits the E.164 digits without the leading {@code '+'}
233	     * @return the country-code portion of {@code digits}
234	     */
235	    private static String extractCountryCode(String digits) {
236	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
237	            String code = entry.getKey();
238	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
239	                return code;
240	            }
241	        }
242	        return digits.substring(0, 1);
243	    }
