269	    /**
270	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
271	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
272	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
273	     * elapsed from the birth date to the registration date (defaulting to the server's current date
274	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
275	     *
276	     * @return the age band, or {@code null} when the birth date is absent
277	     */
278	    public String getAgeBand() {
279	        if (this.birthDate == null) {
280	            return null;
281	        }
282	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
283	        int years = Period.between(this.birthDate, asAt).getYears();
284	        if (years < 18) {
285	            return "MINOR";
286	        }
287	        if (years < 65) {
288	            return "ADULT";
289	        }
290	        return "SENIOR";
291	    }
