301	    /**
302	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
303	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
304	     * from the owner's own customer code and registration date; {@code null} when either is absent.
305	     *
306	     * @return the membership number, or {@code null} when it cannot be derived
307	     */
308	    public String getMembershipNumber() {
309	        if (this.customerCode == null || this.registrationDate == null) {
310	            return null;
311	        }
312	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
313	    }
314	
315	    /**
316	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
317	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
318	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
319	     *
320	     * @return the Luhn check digit, or {@code null} when the customer code is absent
321	     */
322	    public Integer getCheckDigit() {
323	        if (this.customerCode == null) {
324	            return null;
325	        }
326	        int sum = 0;
327	        boolean dbl = true;
328	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
329	            char c = this.customerCode.charAt(i);
330	            if (c < '0' || c > '9') {
331	                continue;
332	            }
333	            int d = c - '0';
334	            if (dbl) {
335	                d *= 2;
336	                if (d > 9) {
337	                    d -= 9;
338	                }
339	            }
340	            sum += d;
341	            dbl = !dbl;
342	        }
343	        return (10 - (sum % 10)) % 10;
344	    }
345	
346	    /**
347	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
348	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
349	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
350	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure exceeds 365 days (see
351	     * {@link #getTenureDays()}). Because a newly created owner has zero tenure, the tenure points are
352	     * never awarded at create time.
353	     *
354	     * @return the membership points, a non-negative integer
355	     */
356	    public Integer getMembershipPoints() {
357	        int points = 0;
358	        boolean hasEmail = this.email != null && !this.email.isBlank();
359	        if (hasEmail) {
360	            points += 2;
361	        }
362	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
363	        if (hasNoNamesakes) {
364	            points += 1;
365	        }
366	        if (this.householdSize != null && this.householdSize >= 3) {
367	            points += 2;
368	        }
369	        Long tenureDays = getTenureDays();
370	        if (tenureDays != null && tenureDays > 365) {
371	            points += 3;
372	        }
373	        return points;
374	    }
375	
376	    /**
377	     * The owner's numeric membership level, mapped from the {@link #getMembershipPoints() membership
378	     * points}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
379	     * for 6 or more points.
380	     *
381	     * @return the membership level, an integer from 1 to 4
382	     */
383	    public Integer getMembershipLevel() {
384	        int points = getMembershipPoints();
385	        if (points <= 1) {
386	            return 1;
387	        }
388	        if (points <= 3) {
389	            return 2;
390	        }
391	        if (points <= 5) {
392	            return 3;
393	        }
394	        return 4;
395	    }
396	
397	    /**
398	     * The owner's tenure in whole days, the number of days elapsed from the
399	     * {@link #getRegistrationDate() registration date} to the server's current date. A tenure of more
400	     * than 365 days is what raises the {@link #getMembershipLevel() membership level} to 4. Returns
401	     * {@code null} when no registration date has been set yet.
402	     *
403	     * @return the tenure in whole days, or {@code null} when the registration date is absent
404	     */
405	    public Long getTenureDays() {
406	        if (this.registrationDate == null) {
407	            return null;
408	        }
409	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
410	    }
411	
412	    /**
413	     * The owner's locality, the canonical region string. Once the owner has a
414	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
415	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
416	     * source of truth. Before the customer code is assigned (for example while a create is still
417	     * validating the postcode) it falls back to the region the code will be built from: the
418	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
419	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
420	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
421	     *
422	     * @return the canonical region string, or {@code 'UNKNOWN'}
423	     */
424	    public String getLocality() {
425	        if (this.customerCode != null) {
426	            int dash = this.customerCode.indexOf('-');
427	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
428	        }
429	        return deriveRegion();
430	    }
431	
432	    /**
433	     * The owner's IANA timezone name, derived from the owner's {@link #getLocality() locality} via the
434	     * fixed region-to-timezone table: NSW->Australia/Sydney, VIC->Australia/Melbourne,
435	     * QLD->Australia/Brisbane. Returns {@code null} when the locality is not one of these regions (for
436	     * example the {@code 'UNKNOWN'} locality of a city with no known region).
437	     *
438	     * @return the IANA timezone name, or {@code null} when the locality has no mapped timezone
439	     */
440	    public String getTimezone() {
441	        return REGION_TIMEZONE.get(getLocality());
442	    }
443	
444	    /**
445	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
446	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
447	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
448	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
449	     * the same region for known cities but disambiguates cities that share a name.
450	     *
451	     * @return the canonical region string, or {@code 'UNKNOWN'}
452	     */
453	    private String deriveRegion() {
454	        String region = regionFromPostcode();
455	        if (region != null) {
456	            return region;
457	        }
458	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
459	    }
460	
461	    /**
462	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
463	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
464	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
465	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
466	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
467	     * owner's region, telephone and last name. Call this once at create time and store the result via
468	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
469	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
470	     *
471	     * @return the assembled customer code
472	     */
473	    public String buildCustomerCode() {
474	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
475	    }
476	
477	    /**
478	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
479	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
480	     *
481	     * @param value the value to hash
482	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
483	     */
484	    private static String sha256Hex8(String value) {
485	        try {
486	            byte[] digest = MessageDigest.getInstance("SHA-256")
487	                .digest(value.getBytes(StandardCharsets.UTF_8));
488	            StringBuilder hex = new StringBuilder(8);
489	            for (int i = 0; i < 4; i++) {
490	                hex.append(String.format("%02X", digest[i]));
491	            }
492	            return hex.toString();
493	        }
494	        catch (NoSuchAlgorithmException e) {
495	            throw new IllegalStateException("SHA-256 algorithm not available", e);
496	        }
497	    }
498	
499	    /**
500	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
501	     * absent, not a 4-digit number, or in no known range.
502	     *
503	     * @return the matching region, or {@code null}
504	     */
505	    private String regionFromPostcode() {
506	        if (this.postcode == null) {
507	            return null;
508	        }
509	        int value;
510	        try {
511	            value = Integer.parseInt(this.postcode.trim());
512	        }
513	        catch (NumberFormatException ex) {
514	            return null;
515	        }
516	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
517	            int[] range = entry.getValue();
518	            if (value >= range[0] && value <= range[1]) {
519	                return entry.getKey();
520	            }
521	        }
522	        return null;
523	    }
524	
525	    /**
526	     * The owner's preferred contact channel, derived from the owner's details. Returns
527	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
528	     *
529	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
530	     */
531	    public String getContactPreference() {
532	        boolean hasEmail = this.email != null && !this.email.isBlank();
533	        return hasEmail ? "EMAIL" : "PHONE";
534	    }
535	
536	    /**
537	     * The owner's identity key, the single derived value used for duplicate detection. It is the
538	     * owner's normalized telephone, email (empty when absent) and household id joined with
539	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
540	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
541	     * are equal, so two members of the same household with different telephones differ here and are
542	     * both allowed.
543	     *
544	     * @return the derived identity key
545	     */
546	    public String getIdentityKey() {
547	        return (this.telephone == null ? "" : this.telephone) + "|"
548	            + (this.email == null ? "" : this.email) + "|"
549	            + (this.householdId == null ? "" : this.householdId);
550	    }
551	
552	    public String getHouseholdId() {
553	        return this.householdId;
554	    }
555	
