572	    public void setHouseholdSize(Integer householdSize) {
573	        this.householdSize = householdSize;
574	    }
575	
576	    public String getPostcode() {
577	        return this.postcode;
578	    }
579	
580	    public void setPostcode(String postcode) {
581	        this.postcode = postcode;
582	    }
583	
584	    public Boolean getBulkSignupWarning() {
585	        return this.bulkSignupWarning;
586	    }
587	
588	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
589	        this.bulkSignupWarning = bulkSignupWarning;
590	    }
591	
592	    public Boolean getPossibleDuplicate() {
593	        return this.possibleDuplicate;
594	    }
595	
596	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
597	        this.possibleDuplicate = possibleDuplicate;
598	    }
599	
600	    public Integer getPossibleDuplicateOf() {
601	        return this.possibleDuplicateOf;
602	    }
603	
604	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
605	        this.possibleDuplicateOf = possibleDuplicateOf;
606	    }
607	
608	    /**
609	     * Whether this owner has been soft-deleted. A newly created owner is not deleted
610	     * ({@code false}); the DELETE endpoint marks the owner deleted ({@code true}) while retaining the
611	     * row, and the create endpoint's duplicate and identity checks ignore owners flagged deleted.
612	     *
613	     * @return whether the owner has been soft-deleted
614	     */
615	    public boolean isDeleted() {
616	        return this.deleted;
617	    }
618	
619	    public void setDeleted(boolean deleted) {
620	        this.deleted = deleted;
621	    }
622	
623	    /**
624	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
625	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
626	     */
627	    @PrePersist
628	    void onCreate() {
629	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
630	    }
631	
632	    /**
633	     * Resolves the effective registration date and rolls it onto a business day. An absent
634	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
635	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
636	     * holiday: starting from the effective date, the date advances one day at a time while it lands
637	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
638	     * non-holiday business day. A date already on a business day is returned unchanged.
639	     *
640	     * <p>This is the single definition of both the defaulting and the business-day roll, used
641	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
642	     * stamps the owner and by the create endpoint that counts owners per business day.
643	     *
644	     * @param supplied the registration date from the request, or {@code null} when none was supplied
645	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
646	     */
647	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
648	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
649	        while (!isBusinessDay(effective)) {
650	            effective = effective.plusDays(1);
651	        }
652	        return effective;
653	    }
654	
655	    /**
656	     * The fixed list of public holidays that the registration date rolls past, alongside weekends.
657	     */
658	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
659	        LocalDate.of(2026, 1, 1),
660	        LocalDate.of(2026, 1, 26),
661	        LocalDate.of(2026, 4, 25),
662	        LocalDate.of(2026, 12, 25),
663	        LocalDate.of(2026, 12, 28));
664	
665	    /**
666	     * A business day is any date that is neither a weekend day nor a listed public holiday.
667	     */
668	    private static boolean isBusinessDay(LocalDate date) {
669	        DayOfWeek day = date.getDayOfWeek();
670	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
671	    }
672	
673	    protected Set<Pet> getPetsInternal() {
674	        if (this.pets == null) {
675	            this.pets = new HashSet<>();
676	        }
677	        return this.pets;
678	    }
679	
680	    protected void setPetsInternal(Set<Pet> pets) {
681	        this.pets = pets;
682	    }
