684	    public List<Pet> getPets() {
685	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
686	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
687	        return Collections.unmodifiableList(sortedPets);
688	    }
689	
690	    public void setPets(List<Pet> pets) {
691	        this.pets = new HashSet<>(pets);
692	    }
693	
694	    public void addPet(Pet pet) {
695	        getPetsInternal().add(pet);
696	        pet.setOwner(this);
697	    }
698	
699	    /**
700	     * Return the Pet with the given name, or null if none found for this Owner.
701	     *
702	     * @param name to test
703	     * @return true if pet name is already in use
704	     */
705	    public Pet getPet(String name) {
706	        return getPet(name, false);
707	    }
708	
709	    /**
710	     * Return the Pet with the given name, or null if none found for this Owner.
711	     *
712	     * @param name to test
713	     * @return true if pet name is already in use
714	     */
715	    public Pet getPet(String name, boolean ignoreNew) {
716	        name = name.toLowerCase();
717	        for (Pet pet : getPetsInternal()) {
718	            if (!ignoreNew || !pet.isNew()) {
719	                String compName = pet.getName();
720	                compName = compName.toLowerCase();
721	                if (compName.equals(name)) {
722	                    return pet;
723	                }
724	            }
725	        }
726	        return null;
727	    }
728	
729	    public Pet getPet(Integer petId) {
730	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
731	    }
732	
733	    @Override
734	    public String toString() {
735	        return new ToStringCreator(this)
736	
737	            .append("id", this.getId())
738	            .append("new", this.isNew())
739	            .append("lastName", this.getLastName())
740	            .append("firstName", this.getFirstName())
741	            .append("address", this.address)
742	            .append("city", this.city)
743	            .append("telephone", this.telephone)
744	            .toString();
745	    }
746	}
